import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 24 · everyday recipe: Sunday pot roast
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, in nineteen fifty-five, Sunday in our house had a smell. My mother put the pot roast in the oven before we left for church at nine thirty, and when we walked back in the door at noon, the whole house smelled like beef and onions and gravy. Danny would run straight to the kitchen in his church shoes. My father would just stand in the hall with his hat in his hand and breathe.""",
   "pot roast dutch oven vegetables", "SUNDAY HAD A SMELL")
sc("""Today, people tell me their pot roast comes out tough and stringy, like chewing on a shoe, and the gravy is thin and gray. So tonight I'm giving you my mother's Sunday pot roast. Fork-tender meat that falls apart, carrots and potatoes that taste like the gravy, and a gravy so good you'll want to drink it. Every step, and the four mistakes that make pot roast tough.""",
   "tender pot roast shredding fork", "LIKE CHEWING ON A SHOE")

ch("The Sunday roast")
sc("""In the fifties, pot roast was the smartest dinner a mother could make. The cheapest cut of beef in the butcher case, a chuck roast, about forty-nine cents a pound in nineteen fifty-five at our A and P, cooked low and slow until it was as tender as the most expensive steak. My mother said, there's no such thing as a tough cut of meat, honey. Only an impatient cook.""",
   "1950s butcher shop meat counter", "ONLY AN IMPATIENT COOK")
sc("""And it fed us for three days. Sunday was the roast. Monday was roast beef sandwiches with the cold gravy. Tuesday was hash, fried in the big skillet with the last potatoes and an egg on top. Three dinners from one piece of meat. That's how a family of four lived on my father's wages from the plant.""",
   "roast beef sandwich vintage kitchen", "THREE DINNERS FROM ONE ROAST")

sc("""The first pot roast I made for my husband's parents, in nineteen sixty-five, I cooked at four hundred degrees for an hour and a half because I was nervous it wouldn't be ready. It was so tough his father sawed at it with a steak knife for five minutes without saying a word. His mother patted my hand and said, next time, dear, give it time. I never forgot it. Give it time.""",
   "1960s family dinner table formal", "GIVE IT TIME")

ch("What you need")
sc("""Here's what you need, honey. One chuck roast, about three to four pounds, with nice white streaks of fat running through it. Don't buy a lean roast. The fat and the connective tissue melt into the meat while it cooks, and that's what makes it tender. A lean roast will be dry no matter what you do.""",
   "raw chuck roast marbled beef", "THE WHITE STREAKS")
sc("""Then. Two tablespoons of oil. Two teaspoons of salt and a teaspoon of black pepper. Two onions, cut in big wedges. Three cloves of garlic. Two tablespoons of tomato paste. One cup of beef broth and one cup of water. Two bay leaves and a few sprigs of thyme, or a teaspoon of dried. And for the vegetables, six carrots in big chunks, and two pounds of small potatoes.""",
   "carrots potatoes onions vegetables board", "BIG CHUNKS")
sc("""And you need a heavy pot with a tight lid. A Dutch oven is best. My mother had a black cast iron one that belonged to Grandma Pearl, so heavy I couldn't lift it with one hand until I was twelve. Heavy pots hold the heat even, so the meat cooks slow and steady and never scorches.""",
   "cast iron dutch oven stove", "A HEAVY POT")

ch("Step by step")
sc("""Step one. Take the roast out of the icebox an hour before, and pat it completely dry with paper towels. Then salt and pepper it all over, every side. A dry roast browns. A wet roast steams and turns gray. That's the first difference between a pot roast that tastes like something and one that tastes like boiled beef.""",
   "seasoning raw beef roast salt", "PAT IT DRY")
sc("""Step two. Heat the oven to three hundred degrees. Heat the oil in the pot on the stove until it shimmers, and lay the roast in. Now leave it alone, honey. Don't poke it, don't move it. Let it sit for four or five minutes until the bottom is deep brown, almost like chocolate. Then turn it and brown every side the same way.""",
   "browning beef roast pot sear", "ALMOST LIKE CHOCOLATE")
sc("""Step three. Take the roast out and put it on a plate. Put the onions in the pot and cook them about five minutes, stirring, until they're soft and golden. Add the garlic and the tomato paste and stir one more minute. Then pour in the broth and water, and scrape up every brown bit stuck to the bottom of the pot with your wooden spoon. Those brown bits are the whole flavor of your gravy.""",
   "scraping pot wooden spoon onions", "THE BROWN BITS")
sc("""Step four. Put the roast back in, with any juice from the plate. The liquid should come about halfway up the sides of the meat, not cover it. Tuck in the bay leaves and thyme. Put the lid on tight and slide the whole pot into the oven. And leave it there for three hours.""",
   "dutch oven lid oven", "HALFWAY UP THE SIDES")
sc("""Step five. After about two hours, take it out, put the carrots and potatoes around the roast in the liquid, and put it back in for one more hour. If you put the vegetables in at the start, they turn to mush. My mother learned that from Grandma Pearl, who learned it the hard way in nineteen twenty-two, the first Sunday she was married.""",
   "carrots potatoes around roast pot", "NOT AT THE START")
sc("""How do you know it's done? Stick a fork in it and twist. If it pulls apart easily, it's done. If it fights you, it's not ready. Put the lid back on and give it thirty more minutes. That's the whole secret, honey. Pot roast isn't done by the clock. It's done when it falls apart.""",
   "fork testing tender pot roast", "WHEN IT FALLS APART")

sc("""And if you don't want to heat the oven for three hours, sweetheart, a slow cooker works too. Do the browning on the stove first, never skip that, then put everything in the slow cooker on low for eight hours, vegetables on the bottom and the roast on top. Start it before work and dinner is ready when you walk in the door. My mother would have loved one of those.""",
   "slow cooker pot roast kitchen", "BEFORE WORK")

ch("The gravy")
sc("""Take the roast and vegetables out onto a warm platter and cover them with foil. Now the gravy. Tilt the pot and spoon off most of the fat that floats on top. Then put the pot on the stove over medium heat. Shake two tablespoons of flour with half a cup of cold water in a jar, and stir it slowly into the bubbling juice. Cook for three minutes until it's thick and glossy.""",
   "gravy simmering pot spoon", "THICK AND GLOSSY")
sc("""Taste it, and add salt and pepper until it's right. If it's too thick, a splash of water. If it's pale, my mother's trick, a teaspoon of Worcestershire sauce or a little splash of strong coffee. Nobody can tell it's coffee. It just tastes deeper, like it cooked all day. Which it did.""",
   "gravy boat pouring roast", "A SPLASH OF COFFEE")

ch("Four mistakes")
sc("""So the four mistakes, sweetheart. Mistake one, a lean roast. Buy chuck, with the fat in it. Mistake two, skipping the browning. If you just put the raw roast in the pot with water, you get gray meat and gray gravy. Five minutes a side makes all the difference.""",
   "browned seared beef close up", "GRAY MEAT, GRAY GRAVY")
sc("""Mistake three, too hot an oven. People turn it up to three fifty or four hundred to hurry it. High heat squeezes the meat tight like a fist, and it gets stringy and dry. Low and slow. Three hundred degrees. And mistake four, taking it out too soon. If it's tough, it isn't overcooked. It's undercooked. Give it more time.""",
   "oven dial temperature kitchen", "TOUGH MEANS NOT DONE")

ch("Serving and leftovers")
sc("""Slice it thick against the grain, or just pull it apart with two forks, and lay it on the platter with the carrots and potatoes all around. Pour some gravy over the top and put the rest in a gravy boat. In our house, it came with a basket of soft rolls and a dish of green beans, and my father said the blessing a little longer on Sundays.""",
   "pot roast platter family table", "A LITTLE LONGER ON SUNDAYS")
sc("""And Monday's sandwich, honey. Cold roast sliced thin, on white bread with a little cold gravy spread on like butter, salt and pepper. My father called it the best sandwich in Ohio. Or warm it in the gravy and put it on a toasted bun. And keep the leftovers in the gravy, so the meat stays moist. Four days in the icebox, or three months in the freezer.""",
   "roast beef sandwich bread", "THE BEST SANDWICH IN OHIO")
sc("""And Tuesday's hash. Chop the leftover roast and potatoes small, with a chopped onion. Fry it all in a hot skillet with a little butter, pressing it flat, and don't stir it for five minutes so the bottom gets a brown crust. Turn it, crisp the other side, and put a fried egg on top. Danny would eat two plates and ask for a third.""",
   "hash skillet fried egg breakfast", "DANNY ASKED FOR A THIRD")

ch("Grandma's kitchen")
sc("""So one more time, sweetheart. A chuck roast with fat in it. Pat it dry, salt it, and brown it like chocolate. Onions, tomato paste, scrape up the brown bits. Liquid halfway up, lid on, three hundred degrees for three hours. Vegetables in for the last hour. It's done when it falls apart. That's my mother's Sunday pot roast, and it has never once been tough.""",
   "Sunday dinner pot roast family", "NEVER ONCE TOUGH")
sc("""Tell me in the comments, honey. What did your family eat after church on Sunday? I bet I can guess. Every day I'm bringing you another recipe from my kitchen, the way my mother made it. Good night, sweetheart.""",
   "vintage kitchen Sunday afternoon light", "WHAT WAS YOUR SUNDAY DINNER?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma24", "The Sunday Pot Roast EVERYONE's Grandma Made (Why Yours Comes Out TOUGH)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Recipe as written by Grandma Ruth: 3 to 4 lb chuck roast, browned; 2 onions, 3 garlic cloves, 2 tbsp tomato paste, 1 cup beef broth, 1 cup water, bay leaves, thyme; covered at 300 F about 3 hours, carrots and potatoes added for the last hour.",
      "Mid-1950s US retail beef prices, chuck roast."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
